questionvariables.text:
plist: [[0,12,5,"h",10,["OM","VO","AC","AB","OA"]],[1,5.7,5.4,"h",1.8,["AB","VO","AC","OA","OM"]],[2,5.6,4.6,"h",2.5,["OM","AC","AB","OA","VO"]],[3,19,12,"h",16,["OM","VO","AB","AC","OA"]],[0,11,6,"h",6,["OM","AC","VO","AB","OA"]],[1,8.1,8.8,"h",2,["AB","VO","OM","AC","OA"]],[2,5.5,6.3,"e",6,["AB","OA","OM","VO","AC"]],[3,17,15,"e",25,["VO","OM","AC","OA","AB"]],[0,16,17,"e",13,["AB","VO","AC","OM","OA"]],[1,6.6,4.2,"e",5.6,["AB","VO","OM","OA","AC"]]];
/* Design: angle between a sloping edge and the base of a pyramid; six entries give the height, four the sloping edge. Source: adapted from SMP GCSE Higher 2, Chapter 34, B12(b)(ii), and SMP Book 5 (Metric), Chapter 7, Exercise D, Q5(b) (rectangular base). */
CT: [["A model pyramid","cm"],["The roof of a gazebo","m"],["A pyramid tent","m"],["A glass paperweight","cm"]];
ix: 1+rand(10); PP: plist[ix];
ctx: CT[PP[1]+1][1]; un: CT[PP[1]+1][2]; ll: PP[2]; ww: PP[3]; isH: is(PP[4] = "h"); gv: PP[5]; OP: PP[6];
hh: if isH then gv else sqrt(gv^2 - (ll^2+ww^2)/4);
LS: "ABCDVOMN"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[ll/2,ww/2,hh],[ll/2,ww/2,0],[ll,ww/2,0],[ll/2,0,0]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
r4(v) := float(floor(10000*v+1/2)/10000);
SA: r4(sq("OA")); OA: dst("OA");
th: angd("VAO"); fM: angd("VMO"); fN: angd("VNO"); fd: float(atan(hh/dst("AC"))*180/%pi); cp: 90-th;
thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
opts: makelist([o, is(o = "OA"), o], o, OP);
